//! Pair lifecycle. No certificate is generated by `new`/startup; only `create_pair` signs.

use std::sync::Arc;

use crate::storage::{PkiRecord, Storage};

use super::{generate_pair, now_secs, PkiConfig, PkiError, PkiFiles, PkiRuntime, PkiStatus};

#[derive(Clone)]
pub struct PkiService {
    files: PkiFiles,
    store: Storage,
    runtime: PkiRuntime,
    config: PkiConfig,
}

pub struct DownloadBundle {
    pub filename: String,
    pub bytes: Vec<u8>,
}

fn random_id() -> String {
    rand::random::<[u8; 16]>()
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect()
}

fn valid_name(name: &str) -> bool {
    !name.is_empty()
        && name.len() <= 64
        && name
            .bytes()
            .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'-')
}

fn valid_server_name(server_name: &str) -> bool {
    if server_name.is_empty() || server_name.len() > 253 || !server_name.is_ascii() {
        return false;
    }
    if server_name.parse::<std::net::IpAddr>().is_ok() {
        return false;
    }
    server_name.split('.').all(|label| {
        !label.is_empty()
            && label.len() <= 63
            && !label.starts_with('-')
            && !label.ends_with('-')
            && label
                .bytes()
                .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'-')
    })
}

impl PkiService {
    /// Open the file store and eagerly load all previously persisted active pairs.
    /// This must not generate a CA or certificate.
    pub fn new(config: PkiConfig, store: Storage) -> Result<Self, PkiError> {
        config.validate()?;
        let service = Self {
            files: PkiFiles::new(config.dir.clone()),
            store,
            runtime: PkiRuntime::default(),
            config,
        };
        service.load_active_pairs()?;
        Ok(service)
    }

    pub fn runtime(&self) -> &PkiRuntime {
        &self.runtime
    }

    pub fn config(&self) -> &PkiConfig {
        &self.config
    }

    pub fn status(&self) -> Result<PkiStatus, PkiError> {
        let active = self.active_records()?;
        Ok(PkiStatus {
            enabled: self.config.enabled,
            credentials: active.len(),
            tunnel_ready: !self.runtime.resolver.is_empty(),
            waiting_for_credentials: active.is_empty(),
        })
    }

    pub fn list(&self, tenant_id: Option<&str>) -> Result<Vec<PkiRecord>, PkiError> {
        let mut records = self
            .store
            .pki_records(tenant_id)
            .map_err(PkiError::Storage)?;
        for record in &mut records {
            if record.status != "revoked" && record.client_not_after <= now_secs() {
                record.status = "expired".to_string();
            } else if record.status == "waiting" && record.last_connected_at.is_some() {
                record.status = "connected".to_string();
            }
        }
        Ok(records)
    }

    pub fn active_records(&self) -> Result<Vec<PkiRecord>, PkiError> {
        Ok(self
            .list(None)?
            .into_iter()
            .filter(|r| r.status == "waiting" || r.status == "connected")
            .collect())
    }

    fn load_active_pairs(&self) -> Result<(), PkiError> {
        for record in self.active_records()? {
            let loaded = self
                .files
                .load_pair(&record.id, &record.server_name)
                .map_err(|e| match e {
                    PkiError::Io(err) => PkiError::Storage(format!(
                        "active pair {} cannot be loaded: {err}",
                        record.id
                    )),
                    other => other,
                })?;
            let key = loaded.certified_key()?;
            self.runtime
                .resolver
                .insert(&record.server_name, Arc::new(key));
            self.runtime.verifier.add_ca(loaded.ca_cert.clone())?;
            self.runtime
                .pairs_by_server
                .write()
                .expect("pki pair map lock poisoned")
                .insert(record.server_name.clone(), record.id.clone());
        }
        Ok(())
    }

    pub fn create_pair(
        &self,
        name: &str,
        tenant_id: &str,
        server_name: &str,
        server_sans: &[String],
        created_by: &str,
        ca_common_name: &str,
    ) -> Result<PkiRecord, PkiError> {
        if !valid_name(name) {
            return Err(PkiError::Invalid(
                "name must be 1..=64 chars of [a-z0-9-]".into(),
            ));
        }
        if !valid_server_name(server_name) {
            return Err(PkiError::Invalid(
                "server_name must be a lowercase DNS name (not an IP)".into(),
            ));
        }
        if !server_sans.iter().any(|s| s == server_name) {
            return Err(PkiError::Invalid(
                "server_sans must contain server_name".into(),
            ));
        }
        let existing = self.list(None)?;
        if existing.iter().any(|r| {
            (r.status == "waiting" || r.status == "connected")
                && (r.server_name == server_name || (r.tenant_id == tenant_id && r.name == name))
        }) {
            return Err(PkiError::Conflict(
                "an active pair already uses this name or server_name".into(),
            ));
        }

        let id = random_id();
        let generated = generate_pair(
            &self.config,
            &id,
            name,
            tenant_id,
            server_name,
            server_sans,
            ca_common_name,
        )?;
        self.files.write_pair(&generated)?;
        let loaded = match self.files.load_pair(&id, server_name) {
            Ok(v) => v,
            Err(e) => {
                self.files.remove_pair(&id);
                return Err(e);
            }
        };
        let key = match loaded.certified_key() {
            Ok(v) => v,
            Err(e) => {
                self.files.remove_pair(&id);
                return Err(e);
            }
        };
        let record = PkiRecord {
            id: id.clone(),
            name: name.to_string(),
            tenant_id: tenant_id.to_string(),
            server_name: server_name.to_string(),
            ca_fingerprint_sha256: generated.ca_fingerprint_sha256,
            server_fingerprint_sha256: generated.server_fingerprint_sha256,
            client_fingerprint_sha256: generated.client_fingerprint_sha256,
            serial: generated.serial,
            status: "waiting".into(),
            created_at: now_secs(),
            created_by: created_by.to_string(),
            downloaded_at: None,
            last_connected_at: None,
            revoked_at: None,
            client_not_after: generated.client_not_after,
        };
        if let Err(e) = self.store.insert_pki_record(&record) {
            self.files.remove_pair(&id);
            return Err(PkiError::Storage(e));
        }
        self.runtime.resolver.insert(server_name, Arc::new(key));
        self.runtime.verifier.add_ca(loaded.ca_cert.clone())?;
        self.runtime
            .pairs_by_server
            .write()
            .expect("pki pair map lock poisoned")
            .insert(server_name.to_ascii_lowercase(), id.clone());
        if !self.runtime.resolver.contains(server_name) {
            return Err(PkiError::Storage(
                "server certificate did not become resolvable".into(),
            ));
        }
        Ok(record)
    }

    pub fn record(&self, id: &str) -> Result<PkiRecord, PkiError> {
        self.store
            .pki_record(id)
            .map_err(PkiError::Storage)?
            .ok_or(PkiError::NotFound)
    }

    pub fn mark_connected(&self, server_name: &str) -> Result<(), PkiError> {
        let id = self
            .runtime
            .pairs_by_server
            .read()
            .expect("pki pair map lock poisoned")
            .get(&server_name.to_ascii_lowercase())
            .cloned();
        if let Some(id) = id {
            self.store
                .mark_pki_connected(&id, now_secs())
                .map_err(PkiError::Storage)?;
        }
        Ok(())
    }

    pub fn download(&self, id: &str) -> Result<DownloadBundle, PkiError> {
        let record = self.record(id)?;
        if record.status == "revoked" || record.revoked_at.is_some() {
            return Err(PkiError::NotFound);
        }
        if record.client_not_after <= now_secs() {
            return Err(PkiError::Expired);
        }
        if record.downloaded_at.is_some() {
            return Err(PkiError::DownloadConsumed);
        }
        let key = self.files.load_client_key(id)?;
        let ca = self.files.load_pair(&record.id, &record.server_name)?;
        let mut tar = tar::Builder::new(Vec::new());
        append_tar(&mut tar, "ca.crt", &ca.ca_cert_pem)?;
        append_tar(&mut tar, "client.crt", &ca.client_cert_pem)?;
        append_tar(&mut tar, "client.key", &key)?;
        let config = format!(
            "# Generated by home-llm-gateway for pair {}\n# Put these files beside this config.\ncloud_addr: \"<gateway-host>:4433\"\nca: ca.crt\ncert: client.crt\nkey: client.key\nserver_name: {}\n",
            record.name, record.server_name
        );
        append_tar(&mut tar, "client-config.example.yml", config.as_bytes())?;
        let bytes = tar.into_inner().map_err(PkiError::Io)?;
        self.store
            .mark_pki_downloaded(id, now_secs())
            .map_err(PkiError::Storage)?;
        self.files.remove_client_key(id)?;
        Ok(DownloadBundle {
            filename: format!("hlmg-client-{}.tar", record.name),
            bytes,
        })
    }

    pub fn revoke(&self, id: &str) -> Result<(), PkiError> {
        let record = self.record(id)?;
        if record.status == "revoked" {
            return Err(PkiError::Conflict("pair is already revoked".into()));
        }
        let loaded = self
            .files
            .load_pair(&record.id, &record.server_name)
            .map_err(|e| PkiError::Storage(format!("cannot revoke pair {id}: {e}")))?;
        let client_cert = {
            let mut cursor = std::io::Cursor::new(&loaded.client_cert_pem);
            rustls_pemfile::certs(&mut cursor)
                .collect::<Result<Vec<_>, _>>()
                .map_err(|e| PkiError::Storage(format!("client.crt: {e}")))?
                .into_iter()
                .next()
                .ok_or_else(|| PkiError::Storage("client.crt is empty".into()))?
        };
        self.runtime.resolver.remove(&record.server_name);
        self.runtime.verifier.remove_ca(&loaded.ca_cert)?;
        self.runtime.verifier.revoke(&client_cert);
        self.runtime
            .pairs_by_server
            .write()
            .expect("pki pair map lock poisoned")
            .remove(&record.server_name.to_ascii_lowercase());
        self.store
            .revoke_pki_record(id, now_secs())
            .map_err(PkiError::Storage)?;
        Ok(())
    }

    pub fn ca_fingerprint_for(&self, record: &PkiRecord) -> String {
        record.ca_fingerprint_sha256.clone()
    }

    pub fn client_cert_fingerprint_for(&self, record: &PkiRecord) -> String {
        record.client_fingerprint_sha256.clone()
    }
}

fn append_tar(tar: &mut tar::Builder<Vec<u8>>, name: &str, bytes: &[u8]) -> Result<(), PkiError> {
    let mut header = tar::Header::new_gnu();
    header.set_size(bytes.len() as u64);
    header.set_mode(0o600);
    header.set_cksum();
    tar.append_data(&mut header, name, bytes)
        .map_err(PkiError::Io)
}

#[cfg(test)]
pub(crate) fn valid_name_for_test(name: &str) -> bool {
    valid_name(name)
}
